import re

class StringFormatter:
    def __init__(self, profile):
        self.profile = profile
        self.cleaned = {}

    def _clean_string(self, value):
        return value.strip()

    def format_email(self):
        raw = self.profile.get('email', '')
        local, domain = raw.split('@')
        return f'{local.lower()}@{domain}'

    def format_phone(self):
        digits = self.profile.get('phone', '')
        return f'({digits[:3]}) {digits[3:6]}-{digits[6:]}'

    def format_name(self):
        first = self._clean_string(self.profile.get('first_name', ''))
        last = self._clean_string(self.profile.get('last_name', ''))
        return f'{last}, {first}'

    def format_date(self):
        raw = self.profile.get('date', '')
        if not re.match(r'^\d{4}-\d{2}-\d{2}$', raw):
            raise ValueError('Date must be in YYYY-MM-DD format')
        year, month, day = raw.split('-')
        months = {
            '01': 'January', '02': 'February', '03': 'March', '04': 'April',
            '05': 'May', '06': 'June', '07': 'July', '08': 'August',
            '09': 'September', '10': 'October', '11': 'November', '12': 'December'
        }
        return f'{day} {months[month]} {year}'

    def display(self):
        lines = [
            f'Name: {self.format_name()}',
            f'Email: {self.format_email()}',
            f'Phone: {self.format_phone()}',
            f'Date: {self.format_date()}'
        ]
        return '\n'.join(lines)

# Test
raw = {
    'first_name': '  Ada  ',
    'last_name': 'LOVELACE',
    'email': ' ADA@EXAMPLE.COM ',
    'phone': '1234567890',
    'date': '2024-06-15'
}
formatter = StringFormatter(raw)
print(formatter.display())
# Output:
# Name: LOVELACE, Ada
# Email: ada@EXAMPLE.COM
# Phone: (123) 456-7890
# Date: 15 June 2024

